                                        <input
                                          type="checkbox"
                                          checked={newRolePermissions.includes(item.key)}
                                          onChange={(e) => {
                                            if (e.target.checked) {
                                              setNewRolePermissions(prev => [...prev, item.key]);
                                            } else {
                                              setNewRolePermissions(prev => prev.filter(p => p !== item.key));
                                            }
                                          }}
                                          className="h-4 w-4 accent-[#414E36] rounded"
                                        />
                                        {item.label}
