                    const emailMatch = pay.employee_accounts?.email?.toLowerCase().includes(q);
                    const idMatch = pay.employee_accounts?.employee_id?.toLowerCase().includes(q);
                    if (!nameMatch && !emailMatch && !idMatch) return false;
