                  if (parts.length < 2) return "—";
                  const year = parts[0];
                  const monthNum = parseInt(parts[1], 10);
                  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
                  const monthName = months[monthNum - 1] || "May";
                  return `05 ${monthName} ${year}`;
